def _require(condition, message):
    assert condition, message


class _Domain:

    def __init__(self, n, edges, f, j):
        self.n = n
        self.edges = edges
        self.f = f
        self.j = j
        _require(type(n) is int and n >= 2, 'active fixture n')
        _require(type(edges) is tuple and type(f) is tuple and (len(f) == n),
            'canonical tuple inputs')
        _require(tuple(sorted(edges)) == edges and len({(a, b) for a, b, q in edges}) == len(edges),
            'canonical edge ordering')
        _require(all(type(x) is int for row in edges for x in row), 'edge exact ints')
        _require(all((0 <= a < b < n and q > 0 for a, b, q in edges)), 'loopless positive support')
        self.deg = tuple(sum((q for a, b, q in edges if v in (a, b))) for v in range(n))
        _require(all((type(x) is int and 0 < x <= d for x, d in zip(f, self.deg, strict=True))),
            'active f')
        self.subsets = {}
        self.quant = {}
        self.pairs = {}
        valid = []
        for size in range(n + 1):
            for tup in combinations(range(n), size):
                U = frozenset(tup)
                mask = sum(2 ** v for v in U)
                self.subsets[mask] = U
                s = sum(f[v] for v in U)
                interior = sum((q for a, b, q in edges if a in U and b in U))
                boundary = sum((q for a, b, q in edges if (a in U) != (b in U)))
                d = sum(self.deg[v] for v in U)
                _require(d == 2 * interior + boundary, 'degree identity')
                self.quant[mask] = (s, interior, boundary, d)
                if j == 0:
                    c, h = (s + boundary - 1, d - s + 1)
                    ok = (s + boundary) % 2 == 1
                elif j == 1:
                    c, h = (s + boundary - 2, d - s)
                    ok = (s + boundary) % 2 == 0 and boundary > 0 and (d > s)
                elif j == 2:
                    c, h = (boundary - d, s - 1)
                    ok = s % 2 == 1 and s >= 3
                else:
                    c, h = (boundary - d - 2, s)
                    ok = s % 2 == 0 and boundary > 0
                self.pairs[mask] = (c, h)
                if U and ok:
                    _require(h > 0, 'positive source denominator')
                    valid.append(mask)
        self.domain = tuple(sorted(valid))
        self.comparison = (None if not valid else self.pairs[min(self.domain,
            key=lambda u: Fraction(*self.pairs[u]))])
        self.optimizers = (tuple(u for u in self.domain if Fraction(*self.pairs[u]) == Fraction(
            *self.comparison)))
        tp = frozenset(v for v in range(n) if (f[v] + self.deg[v]) % 2)
        tf = frozenset(v for v in range(n) if f[v] % 2)
        families = []
        if j == 0:
            families = [(tp, 1, frozenset(), frozenset())]
        elif j == 1:
            for p in range(n):
                if self.deg[p] == f[p]:
                    continue
                for a, b, _q in edges:
                    families.append((tp, 0, frozenset((p, a)), frozenset((b,))))
                    families.append((tp, 0, frozenset((p, b)), frozenset((a,))))
        elif j == 2:
            for v in range(n):
                if f[v] >= 2:
                    families.append((tf, 1, frozenset((v,)), frozenset()))
            for triple in combinations(tuple(v for v in range(n) if f[v] == 1), 3):
                families.append((tf, 1, frozenset(triple), frozenset()))
        else:
            for a, b, _q in edges:
                families.append((tf, 0, frozenset((a,)), frozenset((b,))))
                families.append((tf, 0, frozenset((b,)), frozenset((a,))))
        self.families = families
        self.members = []
        k = ordinary = 0
        for T, parity, forced_in, forced_out in families:
            members = (tuple(sorted((m for m,
                U in self.subsets.items() if forced_in <= U and (not U & forced_out) and (len(
                U & T) % 2 == parity)))))
            self.members.append(members)
            if members:
                k += 1
                N = 2 + n - len(forced_in) - len(forced_out)
                ordinary += N * N - 3 * N + 3
        union = set()
        for a in self.members:
            union.update(a)
        _require(union == set(self.domain), 'independent family coverage')
        self.struct = (len(families), k, k, ordinary)

    def raw(self, u, p):
        a, b = p
        c, h = self.pairs[u]
        return b * c - a * h

    def argmins(self, p):
        if not self.domain:
            return ((), None)
        vals = {u: self.raw(u, p) for u in self.domain}
        minimum = min(vals.values())
        return (tuple(u for u in self.domain if vals[u] == minimum), minimum)

    def query(self, p):
        A, B = p
        n = self.n
        if self.j < 2:
            gamma = tuple(B * self.f[v] + A * (self.f[v] - self.deg[v]) for v in range(n))
            constant = -A - B if self.j == 0 else -2 * B
        else:
            gamma = tuple(-A * self.f[v] - B * self.deg[v] for v in range(n))
            constant = A if self.j == 2 else -2 * B
        arcs = []
        for a, b, q in self.edges:
            arcs.extend(((a, b, B * q), (b, a, B * q)))
        for v, g in enumerate(gamma):
            w = n if g < 0 else n + 1
            arcs.extend(((v, w, abs(g)), (w, v, abs(g))))
        shift = sum(-x for x in gamma if x < 0)
        chosen = None
        chosenfi = chosenpair = None
        for (fi, ((T, parity, forced_in, forced_out), members)) in (enumerate(zip(self.families,
            self.members, strict=True))):
            if not members:
                continue
            source = (forced_in | frozenset((n,)) | (frozenset((n + 2,
                )) if parity == 0 else frozenset()))
            sink = forced_out | frozenset((n + 1,))
            classes = ((source, sink, *tuple(frozenset((v,
                )) for v in range(n) if v not in forced_in | forced_out)))
            mapping = {v: i for i, C in enumerate(classes) for v in C}
            N = len(classes)
            cap = {}
            for a, b, c in arcs:
                x, y = (mapping[a], mapping[b])
                if x != y:
                    cap[x, y] = cap.get((x, y), 0) + c
            baset = T | (frozenset((n + 2,)) if parity == 0 else frozenset())
            terminal = sum((1 << i for i, C in enumerate(classes) if len(C & baset) % 2))
            if terminal.bit_count() % 2:
                terminal ^= 2
            _require(terminal != 0 and terminal.bit_count() % 2 == 0,
                'nonempty transported terminal set')
            allcuts = []
            for X in range(1, 1 << N, 2):
                if X & 2:
                    continue
                val = sum((c for (a, b), c in cap.items() if X >> a & 1 and (not X >> b & 1)))
                U = frozenset((v for i, C in enumerate(classes) if X >> i & 1 for v in C if v < n))
                mask = sum(1 << v for v in U)
                _require(val - shift + constant == self.raw(mask, p),
                    'independent cut/raw identity')
                odd = (X & terminal).bit_count() % 2 == 1
                _require(odd == (len(U & T) % 2 == parity), 'transported parity equivalence')
                allcuts.append((X, val, mask, odd))
            best = None
            fp = None
            for a in range(N):
                if a == 1:
                    continue
                for b in range(N):
                    if b == 0 or a == b:
                        continue
                    restricted = ([row for row in allcuts if row[0] >> a & 1 and (not row[
                        0] >> b & 1)])
                    minval = min(r[1] for r in restricted)
                    minimizers = [r for r in restricted if r[1] == minval]
                    intersection = (1 << N) - 1
                    for row in minimizers:
                        intersection &= row[0]
                    least = next((r for r in minimizers if r[0] == intersection), None)
                    _require(least is not None, 'least ordinary cut belongs to minimizer lattice')
                    if least[3] and (best is None or minval < best[1]):
                        best = least
                        fp = (a, b)
            _require(best is not None, 'feasible family parity minimizer')
            raw = best[1] - shift + constant
            _require(raw == min(self.raw(u, p) for u in members), 'family exact minimum')
            if chosen is None or raw < chosen[1]:
                chosen = (best[2], raw)
                chosenfi = fi
                chosenpair = fp
        args, val = self.argmins(p)
        if not args:
            _require(chosen is None, 'empty source domain')
            return (None, None, None)
        _require(chosen is not None and chosen[0] in args and (chosen[1] == val),
            'global branch exact minimum')
        return (chosen[0], chosenfi, chosenpair)


def _independent_corpus():
    serial = 0
    for n in [2, 3]:
        edgepairs = tuple(combinations(range(n), 2))
        for encoded in product((0, 1, 2), repeat=len(edgepairs)):
            edges = tuple(((p[0], p[1], q) for p, q in zip(edgepairs, encoded, strict=True) if q))
            deg = tuple(sum((q for a, b, q in edges if v in (a, b))) for v in range(n))
            if 0 in deg:
                continue
            for f in product(*(tuple(range(1, x + 1)) for x in deg)):
                yield (serial, n, edges, f)
                serial += 1


def _simulate(m):
    rows = []
    ops = []
    trans = []
    p = (0, 1)
    kind = 'seed'
    stored = None
    newton_saved = None
    c = [0] * 7
    while True:
        args, raw = m.argmins(p)
        U, fi, gr = m.query(p)
        pair = None if U is None else m.pairs[U]
        row = [len(rows), kind, p, U, pair, raw, args, fi, gr, 'pending']
        rows.append(row)
        c[0] += 1
        if kind == 'seed':
            if U is None:
                row[-1] = 'infeasible'
                terminal = 'infeasible'
                root = None
                shore = None
                break
            row[-1] = 'seed'
            p = pair
            kind = 'initial'
            continue
        _require(U is not None, 'no parameter-dependent infeasibility')
        if raw == 0:
            row[-1] = 'terminal'
            terminal = kind
            root = p
            shore = U
            if kind != 'initial':
                c[6] = 1
            if kind == 'reflection':
                newton_saved[-1] = 'superseded'
            _require(Fraction(*p) == Fraction(*m.comparison) and U in m.optimizers,
                'exact terminal root/shore')
            break
        if kind == 'initial':
            _require(raw < 0, 'initial cannot be positive')
            row[-1] = 'retain'
            stored = row
        elif kind == 'newton':
            _require(raw < 0, 'Newton cannot be positive')
            newton_saved = row
            old = stored[2]
            hat = p
            refl = (2 * hat[0] * old[1] - old[0] * hat[1], hat[1] * old[1])
            _require(Fraction(*refl) < Fraction(*hat) < Fraction(*old), 'reflection argument order')
            ops.append((len(rows), hat, old, 2 * hat[0] * old[1], old[0] * hat[1], hat[1] * old[1],
                refl))
            p = refl
            kind = 'reflection'
            c[3] += 1
            continue
        else:
            _require(kind == 'reflection', 'known query phase')
            old = stored
            if raw < 0:
                stored = row
                row[-1] = 'accept'
                newton_saved[-1] = 'superseded'
                c[4] += 1
            else:
                stored = newton_saved
                stored[-1] = 'retain'
                row[-1] = 'reject'
                c[5] += 1
            _require(Fraction(*stored[2]) < Fraction(*old[2]) and stored[5] < 0,
                'retained state invariant')
            _require(stored[4][1] < old[4][1], 'strict active h descent')
            trans.append((old[0], newton_saved[0], row[0], stored[0], stored[2], stored[3],
                stored[4], stored[5]))
        p = stored[4]
        _require(Fraction(*m.comparison) <= Fraction(*p) < Fraction(*stored[2]),
            'fresh Newton progress')
        kind = 'newton'
        c[1] += 1
        c[2] += 1
    return (dict(rows=rows, root=root, shore=shore, counts=c, terminal=terminal,
        structural=m.struct, reflections=ops, transfers=trans))


def _legal_paths(m):
    answers = []

    def visit(kind, p, old, nrecord, prefix):
        opts, raw = m.argmins(p)
        if not opts:
            _require(kind == 'seed', 'infeasible after seed')
            answers.append((*prefix, (kind, p, None)))
            return
        for u in opts:
            pre = (*prefix, (kind, p, u))
            record = (p, u, raw)
            if kind == 'seed':
                visit('initial', m.pairs[u], None, None, pre)
            elif raw == 0:
                answers.append(pre)
            elif kind == 'initial':
                _require(raw < 0, 'initial nonpositive')
                visit('newton', m.pairs[u], record, None, pre)
            elif kind == 'newton':
                _require(raw < 0 and Fraction(*p) < Fraction(*old[0]), 'newton progress')
                A, B = p
                C, D = old[0]
                visit('reflection', (2 * A * D - C * B, B * D), old, record, pre)
            else:
                current = record if raw < 0 else nrecord
                _require(Fraction(*current[0]) < Fraction(*old[0]) and current[2] < 0,
                    'retained pair binding')
                _require(m.pairs[current[1]][1] < m.pairs[old[1]][1], 'finite strict slope descent')
                visit('newton', m.pairs[current[1]], current, None, pre)
    visit('seed', (0, 1), None, None, ())
    return answers


def _bounds(m, r):
    Q = sum((q for _, _, q in m.edges))
    C = 3 * Q + 2
    H = 2 * Q + 1
    checks = pb = xb = 0
    for _step, kind, (A, B), _U, ch, raw, *_ in r['rows']:
        _require(B > 0, 'B positive')
        if kind in ('initial', 'newton'):
            _require(abs(A) <= C and B <= H, 'fresh source bounds')
        for u in m.domain:
            c, h = m.pairs[u]
            _require(abs(c) <= C and 1 <= h <= H, 'source terms bounds')
            _require(abs(B * c - A * h) <= B * C + abs(A) * H, 'raw bounds')
            checks += 1
        pb = max(pb, abs(A).bit_length(), B.bit_length())
        if ch:
            xb = (max(xb, abs(B * ch[0]).bit_length(), abs(A * ch[1]).bit_length(),
                abs(raw).bit_length()))
    for _, (_A, _B), (X, Y), left, right, den, out in r['reflections']:
        P = max(abs(X), Y)
        _require(abs(left) <= 2 * C * P and abs(right) <= H * P and (den <= H * P),
            'reflection temporaries')
        _require(max(abs(out[0]), out[1]) <= (2 * C + H) * P, 'additive encoding recurrence')
        xb = max(xb, abs(left).bit_length(), abs(right).bit_length(), den.bit_length())
    return (checks, pb, xb)

_STATS_FIELDS = (('oracle_calls', 'outer_iterations', 'newton_queries', 'lookahead_queries',
    'lookahead_accepted', 'lookahead_rejected', 'early_returns', 'oracle_stats'))

_EXPORTS = (('AcceleratedBranchStats', 'BranchResult', 'StandardBranchStats',
    'solve_branch_accelerated', 'solve_branch_standard'))

_QUERY_FIELDS = (('atomic_families_examined', 'atomic_families_feasible', 'parity_cut_calls',
    'ordinary_min_cut_calls', 'flow_augmentations', 'flow_bfs_scans', 'flow_peak_generated_value'))

_INPUTS = {row[0]: row[1:4] for row in _U14['INPUTS']}

_CORE_INPUTS = {row[0]: row[1:] for row in _U14['CORE_INPUTS']}

_NAMED_TRACES = {}

_CORE_TRACES = {}

for _row in _U14['TRACES']:
    _NAMED_TRACES.setdefault(_row[0], []).append(_row[1:])

for _row in _U14['CORE_TRACES']:
    _CORE_TRACES.setdefault(_row[:2], []).append(_row[2:])


def _normalize(value):
    if isinstance(value, (list, tuple)):
        return tuple(_normalize(item) for item in value)
    if isinstance(value, dict):
        return {key: _normalize(item) for key, item in value.items()}
    return value


def _digest(value):
    previous = sys.get_int_max_str_digits()
    try:
        sys.set_int_max_str_digits(0)
        data = json.dumps(value, sort_keys=True, separators=(',', ':'), ensure_ascii=True)
        return hashlib.sha256((data + '\n').encode()).hexdigest()
    finally:
        sys.set_int_max_str_digits(previous)


def _named(key):
    name, number = key.rsplit('-j', 1)
    return (_INPUTS[name], int(number))


def _plan(rows):
    return tuple((row[1], row[2], row[3]) for row in rows)


def _expected_plan(domain, plan):
    """Check a fixed plan independently; never choose expectations from a reply.

    This is a finite source-state checker, not a production implementation.
    It validates argmins, parameter/reply binding, retained-state transfer and all
    counters before a test invokes its subject on the plan.
    """
    expected_kind, expected_pair = ('seed', (0, 1))
    current = newton_saved = None
    counts = [0] * 7
    reflections, comparisons, makes, transfers = ([], [], [], [])
    rows = []
    for index, (kind, parameter, shore) in enumerate(plan):
        assert (kind, parameter) == (expected_kind, expected_pair), (index, plan)
        choices, raw = domain.argmins(parameter)
        assert shore in choices if choices else shore is None
        source_pair = None if shore is None else domain.pairs[shore]
        row = (parameter, shore, source_pair, raw)
        rows.append(row)
        counts[0] += 1
        if kind == 'seed':
            if shore is None:
                assert index == len(plan) - 1
                return ((None, None, tuple(counts), 'infeasible', reflections, comparisons, makes,
                    transfers))
            makes.append(source_pair)
            expected_kind, expected_pair = ('initial', source_pair)
            continue
        assert shore is not None
        if kind in ('initial', 'newton'):
            assert raw <= 0
        if kind == 'newton':
            counts[1] += 1
            counts[2] += 1
        if kind == 'reflection':
            counts[3] += 1
        if raw == 0:
            assert index == len(plan) - 1
            assert Fraction(*parameter) == Fraction(*domain.comparison)
            assert shore in domain.optimizers
            counts[6] = int(kind != 'initial')
            return ((parameter, shore, tuple(counts), kind, reflections, comparisons, makes,
                transfers))
        if kind == 'initial':
            current = row
        elif kind == 'newton':
            assert current is not None
            newton_saved = row
            a, b = parameter
            c, d = current[0]
            reflected = (2 * a * d - c * b, b * d)
            assert Fraction(*reflected) < Fraction(*parameter) < Fraction(*current[0])
            reflections.append((parameter, current[0], reflected))
            comparisons.append((reflected, parameter))
            expected_kind, expected_pair = ('reflection', reflected)
            continue
        else:
            assert current is not None and newton_saved is not None
            retained = row if raw < 0 else newton_saved
            counts[4 if raw < 0 else 5] += 1
            comparisons.append((retained[0], current[0]))
            assert Fraction(*retained[0]) < Fraction(*current[0])
            assert retained[3] < 0 and retained[2][1] < current[2][1]
            transfers.append((current, newton_saved, row, retained))
            current = retained
        assert current is not None and current[3] < 0
        expected_kind, expected_pair = ('newton', current[2])
        assert Fraction(*domain.comparison) <= Fraction(*expected_pair) < Fraction(*current[0])
        comparisons.append((expected_pair, current[0]))
        makes.append(expected_pair)
    raise AssertionError('fixed plan ended without a terminal query')


def _stats_tuple(stats):
    return tuple(getattr(stats, name) for name in _QUERY_FIELDS)


def _sum_stats(stats):
    return ((*tuple(sum((row[i] for row in stats)) for i in range(6)), max((row[6]
        for row in stats), default=0)))


def _accounting(counts, terminal):
    calls, iterations, newton, lookahead, accepted, rejected, early = counts
    if terminal == 'infeasible':
        assert counts == (1, 0, 0, 0, 0, 0, 0)
    elif terminal == 'initial':
        assert counts == (2, 0, 0, 0, 0, 0, 0)
    else:
        assert iterations == newton >= 1
        assert calls == 2 + iterations + lookahead and early == 1
        assert accepted + rejected == iterations - 1
        assert lookahead == iterations - int(terminal == 'newton')


def _result_check(result, domain):
    if not domain.domain:
        assert result is None
        return
    assert type(result) is branch_module.BranchResult
    assert type(result.root) is tuple and len(result.root) == 2
    assert all(type(item) is int for item in result.root) and result.root[1] > 0
    assert result.shore in domain.domain
    assert Fraction(*result.root) == Fraction(*domain.comparison)
    assert Fraction(*domain.pairs[result.shore]) == Fraction(*result.root)


def _run_fixed(monkeypatch, inputs, branch, plan, *, real=False, diagnostics=None, context=None):
    domain = _Domain(*inputs, branch)
    expected = _expected_plan(domain, plan)
    root, shore, counts, terminal, reflections, comparisons, makes, transfers = expected
    _accounting(counts, terminal)
    if context is None:
        context = BranchOracleContext(Instance(*inputs))
    state = (context.instance, context.families)
    replies, observed_reflections, observed_comparisons, observed_makes = ([], [], [], [])
    original_query = branch_module.exact_branch_min
    original_make = branch_module.make_pair
    original_compare = branch_module.compare_pairs
    original_reflect = branch_module.pair_reflect

    def query(actual_context, actual_branch, parameter):
        index = len(replies)
        assert actual_context is context and actual_branch == branch
        assert index < len(plan), ('unexpected repeated/extra query', parameter)
        kind, expected_parameter, expected_shore = plan[index]
        assert parameter == expected_parameter, (index, kind, parameter, expected_parameter)
        assert type(parameter) is tuple and all(type(x) is int for x in parameter)
        if real:
            result, stats = original_query(actual_context, actual_branch, parameter)
            assert _stats_tuple(stats)[:4] == domain.struct
        else:
            raw = None if expected_shore is None else domain.raw(expected_shore, parameter)
            result = (None if expected_shore is None else BranchOracleResult(expected_shore,
                *domain.pairs[expected_shore], raw))
            stream = diagnostics[index] if diagnostics is not None else (0,) * 7
            stats = BranchOracleStats(*stream)
        if expected_shore is None:
            assert result is None
        else:
            assert type(result) is BranchOracleResult
            assert ((result.shore, result.c, result.h, result.residual) == (expected_shore,
                *domain.pairs[expected_shore], domain.raw(expected_shore, parameter)))
        replies.append((parameter, result, _stats_tuple(stats)))
        return (result, stats)

    def make(numerator, denominator):
        pair = original_make(numerator, denominator)
        assert len(observed_makes) < len(makes)
        assert pair == makes[len(observed_makes)]
        observed_makes.append(pair)
        return pair

    def compare(left, right):
        assert len(observed_comparisons) < len(comparisons)
        assert (left, right) == comparisons[len(observed_comparisons)]
        answer = original_compare(left, right)
        assert answer == -1
        observed_comparisons.append((left, right))
        return answer

    def reflect(newton, current):
        assert len(observed_reflections) < len(reflections)
        answer = original_reflect(newton, current)
        assert (newton, current, answer) == reflections[len(observed_reflections)]
        observed_reflections.append((newton, current, answer))
        return answer

    def forbidden_plus_one(*args, **kwargs):
        raise AssertionError("Accelerated called Standard's plus-one initializer")
    with monkeypatch.context() as patch:
        patch.setattr(branch_module, 'exact_branch_min', query)
        patch.setattr(branch_module, 'make_pair', make)
        patch.setattr(branch_module, 'compare_pairs', compare)
        patch.setattr(branch_module, 'pair_reflect', reflect)
        patch.setattr(branch_module, 'pair_add_one', forbidden_plus_one)
        result, stats = solve_branch_accelerated(context, branch)
    assert len(replies) == len(plan)
    assert observed_makes == makes and observed_comparisons == comparisons
    assert observed_reflections == reflections
    _result_check(result, domain)
    if result is not None:
        assert result.root == root and result.shore == shore
    assert type(stats) is branch_module.AcceleratedBranchStats
    assert tuple(getattr(stats, name) for name in _STATS_FIELDS[:7]) == counts
    assert _stats_tuple(stats.oracle_stats) == _sum_stats([row[2] for row in replies])
    assert (context.instance, context.families) == state
    assert context.instance is state[0] and context.families is state[1]
    return (result, stats, replies, transfers)


def _load_standard_guard():
    path = Path(__file__).with_name('test_branch.py')
    tree = ast.parse(path.read_bytes())
    node = (next(node for node in tree.body if isinstance(node,
        ast.FunctionDef) and node.name == '_source_violations'))
    namespace = {'ast': ast}
    exec(compile(ast.Module(body=[node], type_ignores=[]), '<standard-source-guard>', 'exec'),
        namespace)
    return namespace['_source_violations']


def _declaration(text, context):

    class IntSubclass(int):
        pass

    class StatsSubclass(BranchOracleStats):
        pass

    class ContextSubclass(BranchOracleContext):
        pass

    class Hostile:

        def __eq__(self, other):
            raise AssertionError('invalid input equality used')

        def __int__(self):
            raise AssertionError('invalid input coercion used')

        def __getattr__(self, name):
            raise AssertionError('invalid input attribute used')
    zero = BranchOracleStats(*(0,) * 7)
    tokens = ({'BOOL': True, 'INT_SUBCLASS': IntSubclass(0), 'FLOAT': 0.0, 'FRACTION': Fraction(0),
        'COERCIBLE': Hostile(), 'NONE': None, 'NEGATIVE_ONE': -1, 'OBJECT': object(),
        'BS_ZERO': zero, 'BS_NONZERO': BranchOracleStats(1, 2, 3, 4, 5, 6, 7),
        'BS_SUBCLASS': StatsSubclass(*(0,) * 7), 'TUPLE': (0,) * 7,
        'STANDARD_STATS': branch_module.StandardBranchStats(0, 0, 0, zero),
        'INSTANCE': context.instance, 'CONTEXT_SUBCLASS': ContextSubclass(context.instance),
        'HOSTILE_CONTEXT': Hostile(), 'CONTEXT_Q1': context})
    previous = sys.get_int_max_str_digits()
    try:
        sys.set_int_max_str_digits(0)
        arguments = ast.literal_eval(text)
    finally:
        sys.set_int_max_str_digits(previous)
    return tuple(tokens[item] if type(item) is str else item for item in arguments)


def _expect_exact(exception, function, *args, **kwargs):
    with pytest.raises(exception) as caught:
        function(*args, **kwargs)
    assert type(caught.value) is exception


def _seam_reply(domain, parameter, shore, fault):

    class TupleSubclass(tuple):
        pass

    class ResultSubclass(BranchOracleResult):
        pass

    class StatsSubclass(BranchOracleStats):
        pass
    zero = BranchOracleStats(*(0,) * 7)
    args = (shore, *domain.pairs[shore], domain.raw(shore, parameter))
    result = BranchOracleResult(*args)
    if fault == 'outer_none':
        return None
    if fault == 'outer_list':
        return [result, zero]
    if fault == 'outer_tuple_subclass':
        return TupleSubclass((result, zero))
    if fault == 'outer_wrong_length':
        return (result, zero, zero)
    if fault == 'wrong_result_type':
        return (object(), zero)
    if fault == 'result_subclass':
        return (ResultSubclass(*args), zero)
    if fault == 'wrong_stats_type':
        return (result, object())
    if fault == 'stats_subclass':
        return (result, StatsSubclass(*(0,) * 7))
    if fault == 'shore_above_universe':
        return (BranchOracleResult(1 << domain.n, *args[1:]), zero)
    if fault == 'raw_plus_one':
        return (BranchOracleResult(*args[:3], args[3] + 1), zero)
    if fault == 'none_after_feasible_seed':
        return (None, zero)
    if fault.startswith('positive_bound_reply'):
        a, b = parameter
        c = abs(a) + 1
        return (BranchOracleResult(shore, c, 1, b * c - a), zero)
    raise AssertionError('unknown registered fault: ' + fault)


def _source_objects(text):
    raw = text.encode() if type(text) is str else text
    lines = raw.splitlines(keepends=True)
    tree = ast.parse(raw)
    definitions = {}
    for node in tree.body:
        if isinstance(node, (ast.ClassDef, ast.FunctionDef)):
            start = min([node.lineno] + [item.lineno for item in node.decorator_list])
            definitions[node.name] = b''.join(lines[start - 1:node.end_lineno])
    return (tree, definitions)


def test_exact_combined_public_surface_signatures_and_record_reuse():
    assert branch_module.__all__ == _EXPORTS
    assert solve_branch_accelerated is branch_module.solve_branch_accelerated
    cls = branch_module.AcceleratedBranchStats
    assert is_dataclass(cls) and cls.__slots__ == _STATS_FIELDS
    assert tuple(field.name for field in fields(cls)) == _STATS_FIELDS
    hints = {name: int for name in _STATS_FIELDS[:7]}
    hints['oracle_stats'] = BranchOracleStats
    assert get_type_hints(cls) == hints
    assert get_type_hints(cls.__init__) == {**hints, 'return': type(None)}
    assert (all(field.default is MISSING and field.default_factory is MISSING for field in fields(
        cls)))
    assert tuple(inspect.signature(cls).parameters) == _STATS_FIELDS
    assert (all(item.kind is inspect.Parameter.POSITIONAL_OR_KEYWORD
        and item.default is inspect.Parameter.empty for item in inspect.signature(
        cls).parameters.values()))
    function = solve_branch_accelerated
    assert tuple(inspect.signature(function).parameters) == ('context', 'branch')
    assert (all(item.kind is inspect.Parameter.POSITIONAL_OR_KEYWORD
        and item.default is inspect.Parameter.empty for item in inspect.signature(
        function).parameters.values()))
    assert (get_type_hints(function) == {'context': BranchOracleContext, 'branch': int,
        'return': tuple[branch_module.BranchResult | None, cls]})
    assert get_type_hints(branch_module.BranchResult) == {'root': RawPair, 'shore': int}
    root = importlib.import_module('exactfrac')
    assert not getattr(root, '__all__', ())
    assert all(not hasattr(root, name) for name in _EXPORTS)


def test_all_seven_valid_statistics_declarations_are_structural_only():
    context = BranchOracleContext(Instance(*_INPUTS['Q1']))
    cls = branch_module.AcceleratedBranchStats
    for identity, target, text, _scope in _U14['VALID_RECORDS']:
        assert target == 'AcceleratedBranchStats'
        args = _declaration(text, context)
        value = cls(*args)
        assert tuple(getattr(value, name) for name in _STATS_FIELDS) == args, identity
        assert value == cls(**dict(zip(_STATS_FIELDS, args, strict=True)))
        assert hash(value) == hash(cls(*args))
        assert not hasattr(value, '__dict__')
        for name in _STATS_FIELDS:
            with pytest.raises(FrozenInstanceError):
                setattr(value, name, 0)
        with pytest.raises((AttributeError, TypeError)):
            value.extra = 1
        with pytest.raises(TypeError):
            _ = value < cls(*args)
        assert tuple(getattr(value, name) for name in _STATS_FIELDS) == args
    zero = BranchOracleStats(*(0,) * 7)
    assert cls(0, 99, 17, 8, 300, 400, 13, zero).lookahead_accepted == 300


def test_all_73_registered_public_rejections_and_python_arity(monkeypatch):
    context = BranchOracleContext(Instance(*_INPUTS['Q1']))

    def forbidden(*args, **kwargs):
        raise AssertionError('invalid public data reached a query')
    monkeypatch.setattr(branch_module, 'exact_branch_min', forbidden)
    for identity, target, text, exception, _guard in _U14['REJECTIONS']:
        args = _declaration(text, context)
        expected = ValueError if exception == 'ValueError' else TypeError
        function = getattr(branch_module, target)
        with pytest.raises(expected) as caught:
            function(*args)
        assert type(caught.value) is expected, identity


def _statistics_order_case(monkeypatch, stop):
    cls = branch_module.AcceleratedBranchStats
    zero = BranchOracleStats(*(0,) * 7)
    good = [1000 + index for index in range(7)] + [zero]
    values = list(good)
    if stop < 8:
        values[stop] = object()
    watched = {id(value): index for index, value in enumerate(values)}
    visited = []

    def observed_type(value):
        index = watched.get(id(value))
        if index is not None and index not in visited:
            visited.append(index)
        return type(value)
    with monkeypatch.context() as patch:
        patch.setattr(branch_module, 'type', observed_type, raising=False)
        if stop < 8:
            _expect_exact(ValueError, cls, *values)
        else:
            cls(*values)
    assert visited == list(range(min(stop + 1, 8)))


def test_statistics_validation_field_order_and_no_later_guard(monkeypatch):
    for stop in range(9):
        _statistics_order_case(monkeypatch, stop)


def test_five_closed_definitions_and_compatibility_bytes_are_preserved():
    source = Path(branch_module.__file__).read_bytes()
    tree, definitions = _source_objects(source)
    five = tuple(row[0] for row in _U14['PRESERVATION'])
    assert (five == ('BranchResult', 'StandardBranchStats', '_checked_query', '_add_diagnostics',
        'solve_branch_standard'))
    assert tuple(definitions) == (*five, 'AcceleratedBranchStats', 'solve_branch_accelerated')
    for name, digest, _start, _end in _U14['PRESERVATION']:
        assert hashlib.sha256(definitions[name]).hexdigest() == digest, name
    from _telemetry_source_audit import assert_test_adaptation, legacy_bytes

    assert (hashlib.sha256(legacy_bytes("tests/test_branch.py")).hexdigest(
        ) == _COMPATIBILITY_SHA256)
    assert_test_adaptation("tests/test_branch.py")
    allowed = (ast.ClassDef, ast.FunctionDef, ast.ImportFrom, ast.Assign, ast.Expr)
    assert all(isinstance(node, allowed) for node in tree.body)
    for node in tree.body:
        if isinstance(node, ast.Assign):
            assert len(node.targets) == 1 and isinstance(node.targets[0], ast.Name)
            assert node.targets[0].id == '__all__'
        if isinstance(node, ast.Expr):
            assert isinstance(node.value, ast.Constant) and type(node.value.value) is str


def test_original_domains_shores_and_all_named_optima_are_independent():
    shores = []
    for name, n, edges, f, degrees, total in _U14['INPUTS']:
        models = [_Domain(n, edges, f, j) for j in range(4)]
        assert models[0].deg == degrees and sum(edge[2] for edge in edges) == total
        for shore in sorted(models[0].subsets):
            if shore == 0:
                continue
            flags = tuple(shore in model.domain for model in models)
            pairs = (tuple((model.pairs[shore] if flags[j] else None for j,
                model in enumerate(models))))
            shores.append((name, shore, *models[0].quant[shore], flags, pairs))
    assert tuple(shores) == _U14['SHORES']
    for key, domain, comparison, optimizers in _U14['OPTIMA']:
        inputs, j = _named(key)
        model = _Domain(*inputs, j)
        assert ((model.domain, model.comparison, model.optimizers) == (domain, comparison,
            optimizers))


def test_all_112_named_actual_trajectories_closed_primitives_and_accounting(monkeypatch):
    seen = set()
    for key, root, shore, terminal, counts, structural, aggregate in _U14['SOLVES']:
        inputs, branch = _named(key)
        result, stats, replies, _transfers = (_run_fixed(monkeypatch, inputs, branch,
            _plan(_NAMED_TRACES[key]), real=True))
        assert key not in seen
        seen.add(key)
