def test_core_census_stream_fingerprints_and_zero_reflection_coverage_boundary():
    census = Counter()
    by_branch = [Counter() for _ in range(4)]
    for row in _U14['CORE_SOLVES']:
        (serial, branch, domain, _comparison, _optimizers, root, shore, terminal, counts,
            structural) = (row)
        model = _Domain(*_CORE_INPUTS[serial], branch)
        run = _simulate(model)
        assert (_normalize((model.domain, model.comparison, model.optimizers, run['root'],
            run['shore'], run['terminal'], run['counts'], run['structural'])) == row[2:])
        assert _normalize(run['rows']) == tuple(_CORE_TRACES[serial, branch])
        paths = _legal_paths(model)
        current = (Counter(solves=1, oracle_calls=counts[0], outer_iterations=counts[1],
            newton_queries=counts[2], lookahead_queries=counts[3], lookahead_accepted=counts[4],
            lookahead_rejected=counts[5], early_returns=counts[6], all_legal_paths=len(paths),
            domain_memberships=len(domain), family_examinations=counts[0] * structural[0],
            feasible_family_calls=counts[0] * structural[1],
            specified_ordinary_calls=counts[0] * structural[3]))
        current[terminal + '_terminal'] += 1
        current['feasible_solves' if root is not None else 'infeasible_solves'] += 1
        if root is not None:
            current['positive_roots' if root[0] > 0 else 'negative_roots' if root[0] < 0 else
                'zero_roots'] += 1
            current['full_shore_returns'] += shore == (1 << model.n) - 1
            current['terminal_pair_distinctions'] += root != run['rows'][-1][4]
        else:
            current['zero_descriptor_infeasible' if structural[0] == 0 else
                'all_empty_infeasible'] += 1
        current['variable_path_length_solves'] += len({len(path) for path in paths}) > 1
        census.update(current)
        by_branch[branch].update(current)
    assert (tuple((j, dict(sorted(value.items()))) for j,
        value in enumerate(by_branch)) == _U14['CORE_BY_BRANCH'])
    census.update(instances=329, n2_instances=5, n3_instances=324)
    assert dict(sorted(census.items())) == dict(_U14['CORE_COUNTS'])
    assert census['lookahead_queries'] == 0
    for stream, digest in _U14['FINGERPRINTS']:
        if stream != 'LARGE_STREAM':
            assert _digest(_U14[stream]) == digest, stream


def _seam_failure_case(monkeypatch, declaration):
    identity, key, failure_step, _kind, fault, _exception, _classification = declaration
    inputs, branch = _named(key)
    domain = _Domain(*inputs, branch)
    plan = _plan(_NAMED_TRACES[key])
    context = BranchOracleContext(Instance(*inputs))
    called = []

    def query(actual_context, actual_branch, parameter):
        step = len(called)
        assert actual_context is context and actual_branch == branch
        assert step <= failure_step, identity
        kind, expected_parameter, shore = plan[step]
        assert parameter == expected_parameter, (identity, kind)
        called.append(parameter)
        if step == failure_step:
            return _seam_reply(domain, parameter, shore, fault)
        return ((BranchOracleResult(shore, *domain.pairs[shore], domain.raw(shore, parameter)),
            BranchOracleStats(*(0,) * 7)))
    with monkeypatch.context() as patch:
        patch.setattr(branch_module, 'exact_branch_min', query)
        _expect_exact(RuntimeError, solve_branch_accelerated, context, branch)
    assert len(called) == failure_step + 1, identity


