def _progress_failure_case(monkeypatch, declaration):
    identity, key, site, fault, _expected = declaration
    inputs, branch = _named(key)
    domain = _Domain(*inputs, branch)
    plan = _plan(_NAMED_TRACES[key])
    context = BranchOracleContext(Instance(*inputs))
    trigger = ({'newton_before_query': 2, 'reflection_before_query': 3,
        'retained_newton_transfer': 4, 'retained_reflection_transfer': 4}[site])
    called, injected = ([], [])
    original_compare = branch_module.compare_pairs

    def query(actual_context, actual_branch, parameter):
        index = len(called)
        assert not injected, identity
        assert actual_context is context and actual_branch == branch
        assert parameter == plan[index][1]
        shore = plan[index][2]
        called.append(parameter)
        return ((BranchOracleResult(shore, *domain.pairs[shore], domain.raw(shore, parameter)),
            BranchOracleStats(*(0,) * 7)))

    def compare(left, right):
        if len(called) == trigger:
            injected.append((left, right))
            return fault[1]
        return original_compare(left, right)
    with monkeypatch.context() as patch:
        patch.setattr(branch_module, 'exact_branch_min', query)
        patch.setattr(branch_module, 'compare_pairs', compare)
        _expect_exact(RuntimeError, solve_branch_accelerated, context, branch)
    assert len(injected) == 1 and len(called) == trigger, identity


