def _dependency_failure_case(monkeypatch, declaration):
    identity, dependency, site, _expected = declaration
    key = 'EQUALITY-j3' if dependency == 'validate_pair' else 'REJECT0-j0'
    inputs, branch = _named(key)
    domain = _Domain(*inputs, branch)
    plan = _plan(_NAMED_TRACES[key])
    context = BranchOracleContext(Instance(*inputs))
    called, thrown = ([], [])
    sentinel = LookupError(identity)
    before = {'seed': 0, 'initial': 1, 'newton': 2, 'reflection': 3, 'retained_transfer': 4}
    after = {'seed': 1, 'reflection': 4, 'terminal_result': len(plan)}
    trigger = (after[site] if dependency in ('_add_diagnostics', 'residual_numerator',
        'validate_pair') else before[site])
    original_dependency = getattr(branch_module, dependency)

    def query(actual_context, actual_branch, parameter):
        assert not thrown
        index = len(called)
        assert index < len(plan) and parameter == plan[index][1]
        assert actual_context is context and actual_branch == branch
        if dependency == 'exact_branch_min' and index == trigger:
            thrown.append(True)
            raise sentinel
        shore = plan[index][2]
        called.append(parameter)
        return ((BranchOracleResult(shore, *domain.pairs[shore], domain.raw(shore, parameter)),
            BranchOracleStats(*(0,) * 7)))

    def seam(*args, **kwargs):
        if len(called) == trigger:
            thrown.append(True)
            raise sentinel
        return original_dependency(*args, **kwargs)
    with monkeypatch.context() as patch:
        patch.setattr(branch_module, 'exact_branch_min', query)
        if dependency != 'exact_branch_min':
            patch.setattr(branch_module, dependency, seam)
        with pytest.raises(LookupError) as caught:
            solve_branch_accelerated(context, branch)
        assert caught.value is sentinel, identity
    assert thrown == [True], identity


