def test_context_preparation_interleaving_six_reuse_steps_and_no_graph_rescan(monkeypatch):
    inputs = _INPUTS['ACCEPT3']
    context = BranchOracleContext(Instance(*inputs))
    instance, families = (context.instance, context.families)

    def forbidden(*args, **kwargs):
        raise AssertionError('prepared context was rebuilt')
    monkeypatch.setattr(oracle_module, 'enumerate_atomic_families', forbidden)
    for _step, name, operation, branch, _expected in _U14['REUSE']:
        assert name == 'ACCEPT3'
        model = _Domain(*inputs, branch)
        if operation == 'accelerated':
            _run_fixed(monkeypatch, inputs, branch, _plan(_NAMED_TRACES[name + '-j' + str(branch)]),
                real=True, context=context)
        elif operation == 'standard':
            result, _stats = branch_module.solve_branch_standard(context, branch)
            _result_check(result, model)
        else:
            assert operation == 'direct_zero'
            result, _stats = oracle_module.exact_branch_min(context, branch, (0, 1))
            choices, minimum = model.argmins((0, 1))
            assert (result is None if not choices else result.shore in choices
                and result.residual == minimum)
        assert context.instance is instance and context.families is families


