def test_all_168_large_graph_solves_symbolic_traces_and_attempted_bit_bounds(monkeypatch):
    large, total, carrier = ([], Counter(), [0, 0, 0])
    specs = {row[0]: row for row in _U14['LARGE_FAMILIES']}
    symbolic = {}
    for row in _U14['SYMBOLIC_TRACES']:
        symbolic.setdefault(row[0], []).append(row)
    invariant_counts = {}
    for (family, exponent, four_counts, terminals, expected_peak, expected_products,
        fingerprint) in (_U14['LARGE_SWEEP']):
        scale = 1 << exponent
        if family == 'POSITIVE':
            inputs = (2, ((0, 1, scale),), (1, 1))
        elif family == 'ZERO':
            inputs = (2, ((0, 1, scale + 1),), (scale + 1, scale + 1))
        else:
            n, edges, f = _INPUTS[specs[family][1]]
            inputs = (n, tuple(((u, v, q * scale) for u, v, q in edges)), f)
        block, peak, products = ([], 0, 0)
        for branch in range(4):
            model = _Domain(*inputs, branch)
            run = _simulate(model)
            plan = _plan(run['rows'])
            _run_fixed(monkeypatch, inputs, branch, plan, real=True)
            assert tuple(run['counts']) == four_counts[branch]
            assert run['terminal'] == terminals[branch]
            bound_count, bound_peak, bound_products = _bounds(model, run)
            carrier[0] += bound_count
            carrier[1] = max(carrier[1], bound_peak)
            carrier[2] = max(carrier[2], bound_products)
            peak, products = (max(peak, bound_peak), max(products, bound_products))
            block.append((family, exponent, branch, *inputs, run))
            counts = run['counts']
            total.update(solves=1, oracle_calls=counts[0], lookahead_queries=counts[3],
                lookahead_accepted=counts[4], lookahead_rejected=counts[5])
            total[run['terminal'] + '_terminal'] += 1
            if family in symbolic and branch == specs[family][3]:
                expected_rows = []
                for row in symbolic[family]:
                    (_, j, step, kind, a1, a0, denominator, shore, c1, c0, h, r1, r0,
                        disposition) = (row)
                    assert j == branch
                    expected_rows.append((step, kind, (a1 * scale + a0, denominator), shore,
                        (c1 * scale + c0, h), r1 * scale + r0, disposition))
                observed = ([(row[0], row[1], row[2], row[3], row[4], row[5],
                    row[9]) for row in run['rows']])
                assert _normalize(observed) == tuple(expected_rows)
                old = invariant_counts.setdefault(family, tuple(counts))
                assert tuple(counts) == old
        assert _digest(block) == fingerprint
        assert (peak, products) == (expected_peak, expected_products)
        large.extend(block)
    assert len(large) == 168 and dict(total) == dict(_U14['LARGE_COUNTS'])
    assert _digest(large) == dict(_U14['FINGERPRINTS'])['LARGE_STREAM']
    assert ('large', *carrier) in _U14['BOUNDS']
    assert total['lookahead_accepted'] > 0 and total['lookahead_rejected'] > 0


def test_all_49_abstract_scalar_recurrences_are_not_graph_coverage():
    previous = {}
    cancellation = 0
    for (exponent, step, newton, current, left, right, denominator, reflected, limit,
        classification) in (_U14['SCALAR_RECURRENCE']):
        assert classification.startswith('abstract')
        a, b = newton
        c, d = current
        assert (2 * a * d, c * b, b * d) == (left, right, denominator)
        assert (left - right, denominator) == reflected
        assert rational_module.pair_reflect(newton, current) == reflected
        assert max(abs(reflected[0]), reflected[1]) <= limit
        if step > 1:
            assert current == previous[exponent]
        if step:
            previous[exponent] = reflected
            assert Fraction(*reflected) < Fraction(*newton) < Fraction(*current)
        else:
            cancellation += 1
            assert reflected[0] == 0 and reflected[1] > 1
    assert cancellation == 7


def test_combined_source_guard_and_accelerated_only_arithmetic_ownership():
    text = Path(branch_module.__file__).read_text()
    assert not _load_standard_guard()(text)
    tree = ast.parse(text)
    solver = (next(node for node in tree.body if isinstance(node,
        ast.FunctionDef) and node.name == 'solve_branch_accelerated'))
    loops = [node for node in ast.walk(solver) if isinstance(node, (ast.For, ast.While))]
    assert len(loops) == 1 and isinstance(loops[0], ast.While)
    assert (all(not isinstance(node, (ast.List, ast.ListComp, ast.Dict, ast.DictComp, ast.Set,
        ast.SetComp, ast.Div, ast.FloorDiv, ast.Mod, ast.Mult,
        ast.Pow)) for node in ast.walk(solver)))
    assert (all(not isinstance(node, ast.Attribute) or node.attr not in ('families', 'instance',
        'edges', 'Q', 'q', 'f', 'd_q', 'bit_length') for node in ast.walk(solver)))
    imports = ({alias.asname or alias.name: alias.name for node in tree.body if isinstance(node,
        ast.ImportFrom) for alias in node.names})
    for node in ast.walk(solver):
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name):
            assert (imports.get(node.func.id, node.func.id) not in ('pair_add_one',
                'solve_branch_standard', 'exact_branch_min'))


def test_legacy_20_negative_controls_and_standard_reflection_leaks_still_fail():
    guard = _load_standard_guard()
    tree = ast.parse(Path(__file__).with_name('test_branch.py').read_bytes())
    test = (next(node for node in tree.body if isinstance(node,
        ast.FunctionDef) and node.name ==
        'test_source_guard_negative_controls_reject_prohibited_constructs'))
    assignment = next(node for node in test.body if isinstance(node, ast.Assign))
    snippets = ast.literal_eval(assignment.value)
    assert len(snippets) == 20
    for snippet in snippets:
        assert guard(snippet), snippet
    legal = ('from .rational import pair_reflect\ndef solve_branch_accelerated(a'
        ',b):\n return pair_reflect(a,b)\n')
    assert not guard(legal)
    faults = ((legal + 'def solve_branch_standard(a,b):\n return pair_reflect(a,b)\n',
        legal + 'def helper(a,b):\n return pair_reflect(a,b)\n',
        legal + ('def solve_branch_standard(a,b):\n return helper(a,b)\ndef helper(a'
        ',b):\n return solve_branch_accelerated(a,b)\n'), legal + 'alias = pair_reflect\n',
        ('from .rational import pair_reflect as reflect\ndef solve_branch_ac'
        'celerated(a,b):\n return reflect(a,b)\ndef solve_branch_standard(a'
        ',b):\n return reflect(a,b)\n'),
        ('from .rational import pair_reflect\ndef solve_branch_accelerated(a'
        ',b):\n def hidden(a,b):\n  return pair_reflect(a,b)\n return hidde' 'n(a,b)\n')))
    for source in faults:
        assert guard(source), source


def test_fresh_process_combined_imports_resolve_only_to_candidate_tree():
    root = Path(__file__).resolve().parents[1]
    script = ('\nimport importlib, json, pathlib, sys\nroot = pathlib.Path(sys.ar'
        'gv[1]).resolve()\nsys.path.insert(0, str(root))\nbefore = set(sys.'
        'modules)\nmodule = importlib.import_module("exactfrac.branch")\nas'
        'sert module.__all__ == (\n    "AcceleratedBranchStats", "BranchRes'
        'ult", "StandardBranchStats",\n    "solve_branch_accelerated", "sol'
        've_branch_standard",\n)\nallowed = {"exactfrac._telemetry", "exactfrac", "exactfrac.branch'
        '", "exactfrac.oracle", "exactfrac.rational",\n           "exactfra'
        'c.instance", "exactfrac.families", "exactfrac.shore", "exactfrac.w'
        'itness",\n           "exactfrac.flow", "exactfrac.sign_routing", "'
        'exactfrac.parity_cut"}\norigins = {}\nfor name in sorted(set(sys.m'
        'odules) - before):\n    if name.startswith(("exactfrac", "tests"))'
        ':\n        assert name in allowed, name\n        path = pathlib.Pa'
        'th(sys.modules[name].__file__).resolve()\n        expected = root '
        '/ ("exactfrac/__init__.py" if name == "exactfrac" else name.replac'
        'e(".", "/") + ".py")\n        assert path == expected, (name, path'
        ')\n        origins[name] = str(path.relative_to(root))\nassert ori'
        'gins["exactfrac.branch"] == "exactfrac/branch.py"\nassert not geta'
        'ttr(sys.modules["exactfrac"], "__all__", ())\nprint(json.dumps(ori'
        'gins, sort_keys=True))\n')
    result = (subprocess.run([sys.executable, '-I', '-B', '-c', script, str(root)], cwd=root,
        env={**os.environ, 'PYTHONDONTWRITEBYTECODE': '1'}, capture_output=True, text=True,
        check=False))
    assert result.returncode == 0, result.stdout + result.stderr
    assert json.loads(result.stdout)['exactfrac.branch'] == 'exactfrac/branch.py'
